test('release, platform, turn, and final inventory validators require the complete exact evidence',()=>{
  assert.equal(validateReleaseResult(releaseResult()).workerVersionId,versionId);assert.equal(validatePlatformProbe(probe()).actorB,'actor-b');assert.equal(validateTenTurnEvidence(tenTurns()).turns.length,10);assert.equal(validateFinalInventory(inventory(),tenTurns().turns[9].revisionId).status,'passed');
  assert.throws(()=>validateReleaseResult({...releaseResult(),phase:'predeploy'}),/release-result-not-passed/);
  const mismatchedManifest=releaseResult();mismatchedManifest.postdeploy.releaseManifest.toolProtocolVersion='changed';assert.throws(()=>validateReleaseResult(mismatchedManifest),/release-identity-mismatch/);
  const mismatchedVersion=releaseResult();mismatchedVersion.postdeploy.workerVersionId='22345678-1234-1234-1234-123456789abc';assert.throws(()=>validateReleaseResult(mismatchedVersion),/release-identity-mismatch/);
  const staleRecheck=releaseResult();staleRecheck.pausedCandidateRecheck.observedAt=31_000;assert.throws(()=>validateReleaseResult(staleRecheck),/paused-recheck-invalid/);
  const swappedApp=releaseResult();[swappedApp.preOpenQuiet.apps[0].image,swappedApp.preOpenQuiet.apps[1].image]=[swappedApp.preOpenQuiet.apps[1].image,swappedApp.preOpenQuiet.apps[0].image];assert.throws(()=>validateReleaseResult(swappedApp),/quiet-proof-invalid/);
  const weak=probe();weak.externalLifecycle=[weak.externalLifecycle[0]];assert.throws(()=>validatePlatformProbe(weak),/release-proof-insufficient/);
  const interrupted=probe();interrupted.internalLifecycle.splice(1,0,{actor:'actor-a',state:'running',observedAt:20_000});assert.throws(()=>validatePlatformProbe(interrupted),/release-proof-insufficient/);
  const missingStart=probe();delete missingStart.actorAStarted;assert.throws(()=>validatePlatformProbe(missingStart),/start-proof-insufficient/);
  const incompleteCleanup=probe();incompleteCleanup.cleanup.actorCleanup[0].status='unconfirmed';assert.throws(()=>validatePlatformProbe(incompleteCleanup),/cleanup-invalid/);
  const staleCleanup=probe();staleCleanup.cleanup.actorCleanup[0].internalLifecycle=structuredClone(staleCleanup.internalLifecycle);staleCleanup.cleanup.actorCleanup[0].externalLifecycle=structuredClone(staleCleanup.externalLifecycle);staleCleanup.cleanup.actorCleanup[0].confirmedAt=staleCleanup.stopProof.observedAt;assert.throws(()=>validatePlatformProbe(staleCleanup),/cleanup-invalid/);
  const inspected=tenTurns();inspected.turns[0].toolEvents.unshift({sequence:1,toolCallId:'list-1',name:'project_list',isError:false});assert.equal(validateTenTurnEvidence(inspected).turns.length,10);
  const duplicateWrite=structuredClone(inspected);duplicateWrite.turns[0].toolEvents.push({sequence:12,toolCallId:'write-extra',name:'project_write',isError:false});assert.throws(()=>validateTenTurnEvidence(duplicateWrite),/material-invalid/);
  const failedRead=structuredClone(inspected);failedRead.turns[0].toolEvents[2].isError=true;assert.throws(()=>validateTenTurnEvidence(failedRead),/material-invalid/);
  const failedInspection=structuredClone(inspected);failedInspection.turns[0].toolEvents[0].isError=true;assert.throws(()=>validateTenTurnEvidence(failedInspection),/material-invalid/);
  const reversed=structuredClone(inspected);reversed.turns[0].toolEvents[1].sequence=13;reversed.turns[0].toolEvents[2].sequence=12;assert.throws(()=>validateTenTurnEvidence(reversed),/material-invalid/);
  for(const name of ['project_edit','project_bash','project_unknown']){const mutated=structuredClone(inspected);mutated.turns[0].toolEvents.unshift({sequence:0,toolCallId:`extra-${name}`,name,isError:false});assert.throws(()=>validateTenTurnEvidence(mutated),/material-invalid/);}
  const missing=tenTurns();missing.turns[1].queuedBehindRelease=false;assert.throws(()=>validateTenTurnEvidence(missing),/release-queue-transition-missing/);
  const nonmonotonic=tenTurns();nonmonotonic.turns[1].transitions[1].observedAt=nonmonotonic.turns[1].transitions[0].observedAt;assert.throws(()=>validateTenTurnEvidence(nonmonotonic),/turn-transition-invalid/);
  const terminalRollback=tenTurns();terminalRollback.turns[1].transitions.splice(1,0,{observedAt:2_001,turnStatus:'completed',activeTurnId:null,releaseHold:{status:'release-pending'}});terminalRollback.turns[1].transitions[2].observedAt=2_002;terminalRollback.turns[1].transitions[3].observedAt=2_003;assert.throws(()=>validateTenTurnEvidence(terminalRollback),/turn-transition-invalid/);
  const lateQueue=tenTurns();[lateQueue.turns[1].transitions[0],lateQueue.turns[1].transitions[1]]=[lateQueue.turns[1].transitions[1],lateQueue.turns[1].transitions[0]];lateQueue.turns[1].transitions[0].observedAt=2_000;lateQueue.turns[1].transitions[1].observedAt=2_001;assert.throws(()=>validateTenTurnEvidence(lateQueue),/release-queue-transition-missing/);
  const noisy=inventory();noisy.applicationObservations[1].active=1;assert.throws(()=>validateFinalInventory(noisy,tenTurns().turns[9].revisionId),/inventory-not-quiet/);
});

