test('post-close reconciliation appends a checksummed proof without modifying the failed source run',async t=>{
  const root=mkdtempSync(join(tmpdir(),'riffology-post-close-reconcile-'));t.after(()=>rmSync(root,{recursive:true,force:true}));const runs=join(root,'docs/evidence/runs'),source=join(runs,'issues-1-6-21-source');mkdirSync(source,{recursive:true,mode:0o700});
  const authPath=join(root,'auth.json');writeFileSync(authPath,JSON.stringify({schemaVersion:1,origin:'https://m1.riff-demo.gaojihe.cn',workspaceId:'workspace-a',sessionId:'session-a',cookie:'private-cookie'}),{mode:0o600});
  const values={'version-manifest.json':{schemaVersion:1,workerSourceSha:sha,workerVersionId:versionId,workerVersionTag:`source-${sha}`},'inventory-preflight.json':{schemaVersion:1,status:'passed',workerSourceSha:sha,workerVersionId:versionId,sessionId:'session-a'},'ten-turns.json':tenTurns(),'final-inventory.json':{schemaVersion:1,status:'blocked',reasonCode:'acceptance-inventory-r2-manifest-read-failed'},'gate-close.json':{schemaVersion:1,status:'blocked'},'acceptance-result.json':{schemaVersion:1,status:'blocked',phase:'gate-close',priorResult:{schemaVersion:1,status:'blocked',phase:'final-inventory',reasonCode:'acceptance-inventory-r2-manifest-read-failed'}}};
  for(const [name,value] of Object.entries(values))writeFileSync(join(source,name),`${JSON.stringify(value)}\n`,{mode:0o600});const sourceNames=Object.keys(values).sort(),sum=sourceNames.map(name=>`${createHash('sha256').update(readFileSync(join(source,name))).digest('hex')}  ${name}`).join('\n')+'\n';writeFileSync(join(source,'SHA256SUMS'),sum,{mode:0o600});const before=new Map([...sourceNames,'SHA256SUMS'].map(name=>[name,createHash('sha256').update(readFileSync(join(source,name))).digest('hex')]));
  const reconciledInventory={...inventory(),auditWorkerVersionId:pausedVersionId,auditTurnsEnabled:false},now=new Date('2026-09-12T01:02:03.004Z');const result=await runPostCloseReconciliation({root,workerSha:sha,sourceRun:source,authInputPath:authPath,auditWorkerVersionId:pausedVersionId,execute:true,inventoryRunner:async input=>{assert.equal(input.auditRelease.workerSourceSha,sha);assert.equal(input.auditRelease.workerVersionId,pausedVersionId);assert.equal(input.auditRelease.turnsEnabled,false);return reconciledInventory;},now});
  assert.equal(result.status,'passed');assert.equal(result.phase,'post-close-reconciled');assert.equal(statSync(result.evidenceDirectory).mode&0o777,0o700);assert.deepEqual(readdirSync(result.evidenceDirectory).sort(),['SHA256SUMS','acceptance-result.json','final-inventory.json','source-run.json']);for(const [name,hash] of before)assert.equal(createHash('sha256').update(readFileSync(join(source,name))).digest('hex'),hash);
  await assert.rejects(()=>runPostCloseReconciliation({root,workerSha:sha,sourceRun:source,authInputPath:authPath,auditWorkerVersionId:pausedVersionId,execute:true,inventoryRunner:async()=>reconciledInventory,now}),/EEXIST/);
  writeFileSync(join(source,'final-inventory.json'),'{}\n',{mode:0o600});await assert.rejects(()=>runPostCloseReconciliation({root,workerSha:sha,sourceRun:source,authInputPath:authPath,auditWorkerVersionId:pausedVersionId,execute:true,inventoryRunner:async()=>reconciledInventory,now:new Date('2026-09-12T01:02:04.004Z')}),/source-checksum-mismatch/);
});

