test('SIGTERM coalesces with normal finalization and waits for one confirmed same-SHA gate close',async t=>{
 const root=mkdtempSync(join(tmpdir(),'riffology-issues-signal-'));t.after(()=>rmSync(root,{recursive:true,force:true}));mkdirSync(join(root,'docs/evidence/runs'),{recursive:true});const releasePath=join(root,'release.json'),authPath=join(root,'auth.json');writeFileSync(releasePath,JSON.stringify(releaseResult()),{mode:0o600});writeFileSync(authPath,JSON.stringify({schemaVersion:1,origin:'https://m1.riff-demo.gaojihe.cn',workspaceId:'workspace-a',sessionId:'session-a',cookie:'private-cookie'}),{mode:0o600});const source=new EventEmitter();let enteredResolve,finishResolve,exitResolve,closes=0;const entered=new Promise(resolve=>{enteredResolve=resolve;}),finish=new Promise(resolve=>{finishResolve=resolve;}),exited=new Promise(resolve=>{exitResolve=resolve;});
 const running=runIssuesAcceptance({root,workerSha:sha,releaseResultPath:releasePath,authInputPath:authPath,execute:true,signalSource:source,signalExit:exitResolve,inventoryPreflight:async()=>{enteredResolve();await finish;return unavailableInventory();},closeRunner:async input=>{closes++;assert.equal(input.workerSha,sha);return {schemaVersion:1,status:'passed',gateCloseConfirmed:true};}});await entered;source.emit('SIGTERM');finishResolve();const result=await running;assert.equal(await exited,143);assert.equal(result.status,'blocked');assert.equal(closes,1);
});

test('signal after submit closes the gate then cancels the exact outstanding turn before exit',async t=>{
 const root=mkdtempSync(join(tmpdir(),'riffology-issues-outstanding-signal-'));t.after(()=>rmSync(root,{recursive:true,force:true}));mkdirSync(join(root,'docs/evidence/runs'),{recursive:true});const releasePath=join(root,'release.json'),authPath=join(root,'auth.json');writeFileSync(releasePath,JSON.stringify(releaseResult()),{mode:0o600});writeFileSync(authPath,JSON.stringify({schemaVersion:1,origin:'https://m1.riff-demo.gaojihe.cn',workspaceId:'workspace-a',sessionId:'session-a',cookie:'private-cookie'}),{mode:0o600});const source=new EventEmitter();let enteredResolve,exitResolve,closed=false,cancelled=0;const entered=new Promise(resolve=>{enteredResolve=resolve;}),exited=new Promise(resolve=>{exitResolve=resolve;});
 const running=runIssuesAcceptance({root,workerSha:sha,releaseResultPath:releasePath,authInputPath:authPath,execute:true,signalSource:source,signalExit:exitResolve,inventoryPreflight:async()=>({schemaVersion:1,status:'passed'}),turnRunner:async(_auth,options)=>{await options.onOutstanding({index:1,turnId:'turn-pending'});enteredResolve();while(!options.shouldAbort())await new Promise(resolve=>setImmediate(resolve));throw Error('acceptance-turn-wait-interrupted');},closeRunner:async()=>{closed=true;return {schemaVersion:1,status:'passed',gateCloseConfirmed:true};},cancelRunner:async(_auth,outstanding)=>{cancelled++;assert.equal(closed,true);assert.equal(outstanding.turnId,'turn-pending');return {schemaVersion:1,status:'passed',turnId:'turn-pending',terminal:{status:'cancelled',neverStarted:true}};},now:new Date('2026-09-11T12:35:00.000Z')});await entered;source.emit('SIGTERM');assert.equal(await exited,143);const result=await running;assert.equal(result.status,'blocked');assert.equal(result.outstandingTurnCleanup.status,'passed');assert.equal(cancelled,1);assert.ok(readdirSync(result.evidenceDirectory).includes('outstanding-turn-cleanup.json'));
});

test('gate closure forward-deploys and verifies the same clean source SHA with admission false',async t=>{
  const root=mkdtempSync(join(tmpdir(),'riffology-gate-close-'));t.after(()=>rmSync(root,{recursive:true,force:true}));mkdirSync(join(root,'infra'),{recursive:true});mkdirSync(join(root,'services/catalog/migrations'),{recursive:true});
  writeFileSync(join(root,'infra','wrangler.m3-vertical-staging.jsonc'),readFileSync(new URL('../../infra/wrangler.m3-vertical-staging.jsonc',import.meta.url)));
  for(const name of ['0001_catalog.sql','0002_auth.sql','0003_provisioning.sql','0004_operator_invitations.sql','0005_initial_operator.sql','0006_model_catalog.sql','0007_model_content_checks.sql','0008_preview_routes.sql'])writeFileSync(join(root,'services/catalog/migrations',name),'-- fixture\n');
  const git=(...args)=>spawnSync('git',args,{cwd:root,encoding:'utf8'});assert.equal(git('init','-q').status,0);assert.equal(git('add','.').status,0);assert.equal(git('-c','user.name=Test','-c','user.email=test@example.invalid','commit','-qm','candidate').status,0);const workerSha=git('rev-parse','HEAD').stdout.trim();
  const id='12345678-1234-1234-1234-123456789abc',calls=[],runner=(_bin,args)=>{calls.push(args);const configPath=args[args.indexOf('--config')+1];assert.equal(JSON.parse(readFileSync(configPath,'utf8')).vars.M2_TURNS_ENABLED,'false');const deployed=deployedFromConfig(configPath,workerSha,id,false);if(args[0]==='deployments')return {status:0,stdout:JSON.stringify({versions:[{version_id:id,percentage:100}]})};if(args[0]==='versions')return {status:0,stdout:JSON.stringify(deployed.version)};if(args[0]==='containers')return {status:0,stdout:JSON.stringify(deployed.apps)};return {status:0,stdout:'',stderr:''};};
  const result=await forwardCloseTurnGate({root,workerSha,execute:true,runner});assert.equal(result.status,'passed');assert.equal(result.gateCloseConfirmed,true);assert.equal(result.workerVersionId,id);assert.equal(calls.filter(args=>args[0]==='deploy'&&!args.includes('--dry-run')).length,1);assert.equal(readdirSync(join(root,'infra')).some(name=>name.startsWith('.vertical-runtime-paused-')),false);
});

